// Builds one HTML email from demand, revenue and failed notifications.
const config = $('Configuration').first().json;
const escape = (value) => String(value ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

const demand = $('Get Waiting Demand').all()
  .map((item) => item.json)
  .filter((row) => row.variant_number)
  .sort((a, b) => b.waiting - a.waiting);
const revenue = $('Get Recovered Revenue').first().json;
const failed = $('Get Failed Notifications').all().map((item) => item.json).filter((row) => row.subscriptionId);

const waitingTotal = demand.reduce((sum, row) => sum + row.waiting, 0);
const topRows = demand.slice(0, Number(config.topProducts) || 10)
  .map((row) => `<tr><td>${escape(row.variant_number)}</td><td>${escape(row.options_label)}</td><td align="right">${row.waiting}</td></tr>`)
  .join('');
const revenueRows = (revenue.currencies ?? [])
  .map((row) => `<li>${row.revenue.toFixed(2)} ${escape(row.iso)} from ${row.orders} orders</li>`)
  .join('') || '<li>No recovered orders yet</li>';

const html = `
<h2>Back in Stock weekly report</h2>
<p><b>${waitingTotal}</b> customers are waiting for <b>${demand.length}</b> products.</p>
<h3>Most requested products</h3>
${topRows ? `<table border="1" cellpadding="4" cellspacing="0"><tr><th>Product number</th><th>Variant</th><th>Waiting</th></tr>${topRows}</table>` : '<p>Nobody is waiting.</p>'}
<h3>Recovered revenue (all time)</h3>
<ul>${revenueRows}</ul>
<h3>Failed notifications</h3>
<p>${failed.length} failed${failed.length && config.retryFailedNotifications ? ', retried by this workflow' : ''}.</p>`;

return [{ json: { subject: `Back in Stock: ${waitingTotal} customers waiting`, html, waitingTotal, failed: failed.length } }];
